// Single entry point for the pipeline's exported JSON. Everything rendered on the site
// comes from these files, regenerated by `python run_all.py`.
import summaryJson from "../../public/data/summary.json";
import leaderboardJson from "../../public/data/leaderboard.json";
import validationJson from "../../public/data/validation_series.json";
import testJson from "../../public/data/test_predictions.json";
import qualityJson from "../../public/data/data_quality.json";
import physicsJson from "../../public/data/physics_diagnostics.json";
import importanceJson from "../../public/data/feature_importance.json";

export type Metrics = {
  n_hours: number;
  mae_kw: number;
  rmse_kw: number;
  bias_kw: number;
  nmae_pct: number;
  nrmse_pct: number;
  daily_energy_mae_mwh: number;
};

export type ModelKey = "persistence" | "b0" | "b1" | "m1" | "m2" | "m3";

export type ModelMeta = {
  key: ModelKey;
  name: string; // exact name used by the pipeline
  short: string;
  role: string;
  color: string;
};

export const MODELS: ModelMeta[] = [
  { key: "persistence", name: "Ref yesterday persistence", short: "Persistence", role: "Yesterday, same hour", color: "var(--c-muted)" },
  { key: "b0", name: "B0 seasonal climatology", short: "B0 Climatology", role: "Season × hour average", color: "var(--c-slate)" },
  { key: "b1", name: "B1 physics (clear-sky x cloud)", short: "B1 Physics", role: "Clear-sky × cloud → PVWatts", color: "var(--c-sky)" },
  { key: "m1", name: "M1 LightGBM (AC clear-sky index)", short: "M1 LightGBM", role: "Learns the clear-sky index", color: "var(--c-ember)" },
  { key: "m2", name: "M2 LightGBM two-stage (POA -> plant curve)", short: "M2 Two-stage", role: "Forecast → POA → plant curve", color: "var(--c-violet)" },
  { key: "m3", name: "M3 final blend (M1 + B1)", short: "M3 Final", role: "½ physics + ½ learned", color: "var(--c-sun)" },
];

export const modelByName = Object.fromEntries(MODELS.map((m) => [m.name, m])) as Record<string, ModelMeta>;

export const summary = summaryJson as {
  final_model: string;
  seasonal_holdout: Metrics;
  skill_vs_climatology_rmse: number;
  lomo_final_mae_kw: number | null;
  test_total_mwh: number;
  test_days: number;
  test_mean_daylight_cloud: number;
  rows_flagged_unusable: number;
  rows_total: number;
};

type Scheme = { label: string; results: Record<string, Metrics> };
export const leaderboard = leaderboardJson as unknown as {
  seasonal_holdout: Scheme;
  forward_holdout: Scheme;
  lomo_mean: Scheme;
  lomo_by_month: (Metrics & { month: string; model: string })[];
};

type ValidationRow = { t: string; actual: number | null; scored: boolean; cloud: number | null; poa: number | null } & Record<string, number | null | string | boolean>;
export type WorstDay = {
  date: string;
  abs_energy_error_mwh: number;
  actual_mwh: number;
  pred_mwh: number;
  forecast_cloud_mean: number;
  realised_clear_sky_index: number;
  rain_mm: number;
};
const validation = validationJson as unknown as { models: string[]; final: string; series: ValidationRow[]; worst_days: WorstDay[] };

/** Compact validation series keyed by model key (keeps the client payload small). */
export type ValPoint = { t: string; actual: number | null; cloud: number | null; poa: number | null } & Partial<Record<ModelKey, number | null>>;
export const validationSeries: ValPoint[] = validation.series.map((r) => {
  const point: ValPoint = { t: r.t, actual: r.actual, cloud: r.cloud, poa: r.poa };
  for (const m of MODELS) point[m.key] = r[m.name] as number | null;
  return point;
});
export const worstDays = validation.worst_days;

export type TestPoint = { t: string; pred: number; m1: number; b1: number; clearsky: number; cloud: number };
export const testForecast = testJson as unknown as { cloud_params: { a: number; b: number }; derate: number; series: TestPoint[] };

type SeriesPoint = Record<string, number | string | null>;
export const quality = qualityJson as unknown as {
  load: {
    rows_raw: number;
    non_iso_timestamps: number;
    was_sorted: boolean;
    missing_values: Record<string, number>;
    sentinels: Record<string, number>;
    status_counts: Record<string, number>;
    duplicate_rows_removed: number;
    conflicting_duplicates: number;
    missing_hours: number;
    rows_clean_grid: number;
  };
  forecast_imputed: Record<string, number>;
  clean: {
    derate_fitted: number;
    flags: Record<string, number>;
    mw_rescaled_days: string[];
    rows_train_ok: number;
    daylight_rows_train_ok: number;
    daylight_rows_total: number;
  };
  examples: {
    mw_logging: { title: string; series: SeriesPoint[] };
    stuck_poa: { title: string; series: SeriesPoint[] };
    ac_flatline: { title: string; series: SeriesPoint[] };
    outage: { title: string; series: SeriesPoint[] };
    spikes: { title: string; points: { t: string; ac_raw: number; poa: number }[] };
  };
};

export const physics = physicsJson as {
  derate: number;
  by_hour: { hour: number; resid_kw: number }[];
  by_month: { month: string; resid_kw: number; rain_mm: number }[];
};

export const importance = importanceJson as { feature: string; gain_pct: number }[];

export const PLANT = {
  name: "Tumakuru PV block",
  location: "Tumakuru district, Karnataka",
  coords: "14.10° N, 77.28° E · 680 m",
  dc: "12.5 MWp",
  ac: "10 MW",
  array: "Fixed tilt 15°, due south",
  tech: "Mono PERC, −0.35 %/°C",
};
